// Объект JavaScript (живой, в памяти)
const user = {
  name: "Alice",
  age: 25,
  active: true
};

// Сериализация: объект → строка JSON
const json = JSON.stringify(user);
console.log(json);  // '{"name":"Alice","age":25,"active":true}'
console.log(typeof json);  // "string" — это ТЕКСТ, не объект!

// Парсинг: строка JSON → объект
const parsed = JSON.parse(json);
console.log(parsed.name);  // Alice — снова объект, снова живой!

const data = { name: "Alice", age: 25 };

// Минимальный формат (для передачи):
console.log(JSON.stringify(data));
// '{"name":"Alice","age":25}'

// С отступами (для чтения):
console.log(JSON.stringify(data, null, 2));
// {
//   "name": "Alice",
//   "age": 25
// }

// 2 — количество пробелов. Можно и табуляцию: JSON.stringify(data, null, "\t")

const json = '{"name":"Bob","age":30}';
const obj = JSON.parse(json);
console.log(obj.name);  // Bob
console.log(obj.age);   // 30
console.log(typeof obj); // "object" — снова объект!

// После parse можно работать как с обычным объектом:
obj.age = 31;
console.log(obj.age);  // 31

// JSON поддерживает:
const supported = {
  str: "hello",       // строка
  num: 42,            // число
  bool: true,         // boolean
  nothing: null,      // null
  arr: [1, 2, 3],     // массив
  nested: { a: 1 }    // объект
};
console.log(JSON.stringify(supported));  // всё сохранится

// JSON НЕ поддерживает (теряется при stringify):
const lost = {
  undef: undefined,   // исчезнет!
  func: () => {},     // исчезнет!
  sym: Symbol("x")    // исчезнет!
};
console.log(JSON.stringify(lost));  // '{}' — пустой объект!

// Безопасный парсинг через try/catch
function safeParse(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    // JSON невалидный — возвращаем null вместо падения
    console.error("Невалидный JSON:", e.message);
    return null;
  }
}

console.log(safeParse('{"name":"Alice"}'));  // { name: "Alice" }
console.log(safeParse("{bad json}"));         // null — без падения!

// Типичный ответ API
const json = '{"user":{"name":"Alice","address":{"city":"Moscow"}}}'
const data = JSON.parse(json);

// Доступ через цепочку точек:
console.log(data.user.address.city);  // Moscow

// Безопасный доступ через optional chaining:
console.log(data.user?.phone?.number);  // undefined — без ошибки

// Обратная сериализация с отступами:
console.log(JSON.stringify(data, null, 2));

// Ответ API: массив пользователей
const json = '[{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]';
const users = JSON.parse(json);

console.log(Array.isArray(users));  // true — это массив

// Работаем как с обычным массивом:
console.log(users[0].name);  // Alice

// Фильтруем и маппим:
const names = users.filter(u => u.id > 1).map(u => u.name);
console.log(names);  // ["Bob"]

// Симуляция цикла клиент-сервер:
// 1. Клиент создаёт объект
const request = { action: "login", user: "alice" };

// 2. Сериализация для отправки
const serialized = JSON.stringify(request);
console.log(serialized);  // '{"action":"login","user":"alice"}'

// 3. Передача по сети (симуляция строковой переменной)
const networkData = serialized;  // сеть передаёт только строку

// 4. На сервере — парсинг
const received = JSON.parse(networkData);
console.log(received.user);  // alice

// JSON — это строка
const json = '{"name":"Alice"}';
console.log(typeof json);  // "string"
console.log(json.name);    // undefined — у строки нет свойства name!

// Объект — это структура
const obj = { name: "Alice" };
console.log(typeof obj);   // "object"
console.log(obj.name);     // "Alice" — работает!

// Нужен parse чтобы превратить строку в объект:
const parsed = JSON.parse(json);
console.log(parsed.name);  // "Alice" — теперь работает

